 using System.Globalization;
 using System.Text.Json;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;
 using Microsoft.Extensions.Logging.Console;
 using TradeRecon.Application.Audit;
 using TradeRecon.Application.Reconciliation;
 using TradeRecon.Application.Reporting;
 using TradeRecon.Domain;
 using TradeRecon.Infrastructure;

 namespace TradeRecon.Console;

 /// <summary>
 /// Console host for the canonical trade-reconciliation baseline. Runs a deterministic
 /// end-of-day reconciliation over the synthetic CSV fixtures and writes the reports.
 ///
 /// This host exposes a stable, black-box-friendly CLI contract:
 ///   * Inputs come from a fixture directory (--fixtures) containing trades.csv,
 ///     settlements.csv and positions.csv.
 ///   * Reports are written under --out/&lt;yyyy-MM-dd&gt;/ as eod-summary.txt,
 ///     eod-break-register.csv and eod-result.json.
 ///   * With --json the deterministic JSON result is written to stdout (and all logs are
 ///     routed to stderr) so stdout contains nothing but the JSON document.
 ///   * Exit codes: 0 = clean, 2 = breaks outstanding, 1 = input/processing error.
 ///
 /// Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures &lt;dir&gt;] [--out &lt;dir&gt;] [--json]
 /// </summary>
 public static class Program
 {
     /// <summary>Reconciliation completed with no open breaks.</summary>
     public const int ExitClean = 0;

     /// <summary>Input or processing error (e.g. missing or malformed fixtures).</summary>
     public const int ExitError = 1;

     /// <summary>Reconciliation completed but open breaks remain.</summary>
     public const int ExitBreaks = 2;

     public static async Task<int> Main(string[] args)
     {
         if (args.Contains("--help") || args.Contains("-h"))
         {
             System.Console.WriteLine(
                 "Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures <dir>] [--out <dir>] [--json]");
             System.Console.WriteLine("Audit subcommands: audit initialize <stateDirectory> | audit propose <stateDirectory> <requestId> <proposer> <businessDate> <reason> <evidence> | audit decide <stateDirectory> <requestId> <approver> <decision> | audit export <stateDirectory> <fromDate> <toDate> <exportPath>");
             return ExitClean;
         }

         if (args.Length > 0 && (string.Equals(args[0], "audit", StringComparison.OrdinalIgnoreCase) || IsAuditVerb(args[0])))
         {
             return await RunAuditCommandAsync(args).ConfigureAwait(false);
         }

         CliOptions options;
         try
         {
             options = CliOptions.Parse(args);
         }
         catch (Exception ex) when (ex is FormatException or ArgumentException or PathTooLongException or NotSupportedException)
         {
             System.Console.Error.WriteLine($"Invalid arguments: {ex.Message}");
             return ExitError;
         }

         using var loggerFactory = LoggerFactory.Create(builder =>
         {
             builder.SetMinimumLevel(LogLevel.Information);
             builder.AddSimpleConsole(o =>
             {
                 o.SingleLine = true;
                 o.TimestampFormat = "HH:mm:ss ";
             });
             // In JSON mode keep stdout pure by sending every log line to stderr.
             if (options.JsonOutput)
             {
                 builder.Services.Configure<ConsoleLoggerOptions>(
                     o => o.LogToStandardErrorThreshold = LogLevel.Trace);
             }
         });

         var services = new ServiceCollection();
         services.AddSingleton<ILoggerFactory>(loggerFactory);
         services.AddLogging();
         services.AddTradeReconCore();
         services.AddTradeReconInfrastructure(options.FixturesDirectory, options.OutputDirectory);

         await using var provider = services.BuildServiceProvider();
         var logger = provider.GetRequiredService<ILogger<object>>();
         var runner = provider.GetRequiredService<ReconciliationRunner>();
         var reportBuilder = provider.GetRequiredService<EndOfDayReportBuilder>();

         var runOptions = new ReconciliationRunOptions
         {
             Tolerances = new ToleranceOptions
             {
                 QuantityAbsolute = 0m,
                 AmountAbsolute = 0.01m,
                 SettlementDateDays = 0,
                 PositionQuantityAbsolute = 0m
             }
         };

         try
         {
             var result = await runner.RunAsync(options.BusinessDate, runOptions).ConfigureAwait(false);

             if (options.JsonOutput)
             {
                 System.Console.Out.Write(reportBuilder.BuildJson(result));
                 System.Console.Out.Write('\n');
             }
             else
             {
                 System.Console.WriteLine();
                 System.Console.WriteLine($"Business date : {result.BusinessDate:yyyy-MM-dd}");
                 System.Console.WriteLine($"Matched pairs : {result.Matches.Count}");
                 System.Console.WriteLine($"Open breaks   : {result.OpenBreaks.Count}");
                 System.Console.WriteLine($"Overridden    : {result.OverriddenBreaks.Count}");
                 System.Console.WriteLine($"Status        : {EndOfDayReportBuilder.StatusText(result)}");
                 System.Console.WriteLine($"Reports       : {options.OutputDirectory}");
             }

             return result.IsClean ? ExitClean : ExitBreaks;
         }
         catch (Exception ex) when (ex is FileNotFoundException or DirectoryNotFoundException or FormatException)
         {
             logger.LogError(ex, "Reconciliation failed: {Message}", ex.Message);
             return ExitError;
         }
     }

     private static async Task<int> RunAuditCommandAsync(string[] args)
     {
         var commandArgs = string.Equals(args[0], "audit", StringComparison.OrdinalIgnoreCase)
            ? args[1..]
            : args;

         if (commandArgs.Length == 0)
         {
            System.Console.WriteLine("{\"ok\":false,\"error\":\"No audit command supplied.\"}");
            return ExitError;
         }

         var command = commandArgs[0];

         try
         {
            var values = ParseAuditArguments(commandArgs);
            switch (command)
            {
                case "initialize":
                    var initializeStateDirectory = GetRequiredAuditValue(values, commandArgs, 0, "stateDirectory");
                    AuditCommandProcessor.Initialize(initializeStateDirectory);
                    WriteAuditJson(new { ok = true, command = "initialize", stateDirectory = initializeStateDirectory, status = "initialized" });
                    return ExitClean;

                case "propose":
                    var proposeStateDirectory = GetRequiredAuditValue(values, commandArgs, 0, "stateDirectory");
                    var requestId = GetRequiredAuditValue(values, commandArgs, 1, "requestId");
                    var proposer = GetRequiredAuditValue(values, commandArgs, 2, "proposer");
                    var proposalDate = GetRequiredAuditValue(values, commandArgs, 3, "businessDate");
                    var reason = GetRequiredAuditValue(values, commandArgs, 4, "reason");
                    var evidence = GetRequiredAuditValue(values, commandArgs, 5, "evidence");
                    var proposal = AuditCommandProcessor.Propose(
                        proposeStateDirectory,
                        requestId,
                        proposer,
                        DateOnly.ParseExact(proposalDate, "yyyy-MM-dd", CultureInfo.InvariantCulture),
                        reason,
                        evidence);
                    WriteAuditJson(new
                    {
                        ok = true,
                        command = "propose",
                        requestId = proposal.RequestId,
                        actor = proposal.Actor,
                        action = proposal.Action,
                        businessDate = proposal.BusinessDate,
                        sequence = proposal.Sequence,
                        previousHash = proposal.PreviousHash,
                        hash = proposal.Hash,
                        timestampUtc = proposal.TimestampUtc,
                        version = proposal.Version
                    });
                    return ExitClean;

                case "decide":
                    var decideStateDirectory = GetRequiredAuditValue(values, commandArgs, 0, "stateDirectory");
                    var decideRequestId = GetRequiredAuditValue(values, commandArgs, 1, "requestId");
                    var approver = GetRequiredAuditValue(values, commandArgs, 2, "approver");
                    var decision = GetRequiredAuditValue(values, commandArgs, 3, "decision");
                    var finalDecision = AuditCommandProcessor.Decide(decideStateDirectory, decideRequestId, approver, decision);
                    WriteAuditJson(new
                    {
                        ok = true,
                        command = "decide",
                        requestId = finalDecision.RequestId,
                        actor = finalDecision.Actor,
                        action = finalDecision.Action,
                        businessDate = finalDecision.BusinessDate,
                        sequence = finalDecision.Sequence,
                        previousHash = finalDecision.PreviousHash,
                        hash = finalDecision.Hash,
                        timestampUtc = finalDecision.TimestampUtc,
                        version = finalDecision.Version
                    });
                    return ExitClean;

                case "export":
                    var exportStateDirectory = GetRequiredAuditValue(values, commandArgs, 0, "stateDirectory");
                    var exportFromDate = GetRequiredAuditValue(values, commandArgs, 1, "fromDate");
                    var exportToDate = GetRequiredAuditValue(values, commandArgs, 2, "toDate");
                    var exportPath = GetRequiredAuditValue(values, commandArgs, 3, "exportPath");

                    var exportPayload = AuditCommandProcessor.Export(
                        exportStateDirectory,
                        DateOnly.ParseExact(exportFromDate, "yyyy-MM-dd", CultureInfo.InvariantCulture),
                        DateOnly.ParseExact(exportToDate, "yyyy-MM-dd", CultureInfo.InvariantCulture));

                    var entries = exportPayload.Entries.Select(entry => new
                    {
                        requestId = entry.RequestId,
                        action = entry.Action,
                        actor = entry.Actor,
                        businessDate = entry.BusinessDate,
                        reason = entry.Reason,
                        evidence = entry.Evidence,
                        sequence = entry.Sequence,
                        previousHash = entry.PreviousHash,
                        hash = entry.Hash,
                        timestampUtc = entry.TimestampUtc,
                        version = entry.Version
                    }).ToList();

                    var jsonPayload = new { entries };
                    var outputJson = JsonSerializer.Serialize(jsonPayload, new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase });
                    var exportDirectory = Path.GetDirectoryName(exportPath);
                    if (!string.IsNullOrWhiteSpace(exportDirectory))
                    {
                        Directory.CreateDirectory(exportDirectory);
                    }

                    await File.WriteAllTextAsync(exportPath, outputJson + Environment.NewLine).ConfigureAwait(false);
                    WriteAuditJson(jsonPayload);
                    return ExitClean;

                default:
                    throw new ArgumentException($"Unknown audit command '{command}'.");
            }
         }
         catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or FormatException or DirectoryNotFoundException or PathTooLongException or NotSupportedException)
         {
            WriteAuditJson(new { ok = false, command = command, error = ex.Message });
            return ExitError;
         }
     }

     private static bool IsAuditVerb(string arg)
         => string.Equals(arg, "initialize", StringComparison.OrdinalIgnoreCase)
            || string.Equals(arg, "propose", StringComparison.OrdinalIgnoreCase)
            || string.Equals(arg, "decide", StringComparison.OrdinalIgnoreCase)
            || string.Equals(arg, "export", StringComparison.OrdinalIgnoreCase);

     private static void WriteAuditJson(object payload)
         => System.Console.WriteLine(JsonSerializer.Serialize(payload, new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));

     private static IReadOnlyDictionary<string, string> ParseAuditArguments(string[] args)
     {
         var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
         var positionals = new List<string>();

         for (var i = 1; i < args.Length; i++)
         {
            var token = args[i];
            if (token.StartsWith("--", StringComparison.Ordinal))
            {
                var key = token.TrimStart('-');
                if (i + 1 >= args.Length || args[i + 1].StartsWith("--", StringComparison.Ordinal))
                {
                    throw new ArgumentException($"Option --{key} requires a value.");
                }

                result[key] = args[++i];
                continue;
            }

            positionals.Add(token);
         }

         if (positionals.Count == 0)
         {
            return result;
         }

         for (var i = 0; i < positionals.Count; i++)
         {
            result[$"position{i}"] = positionals[i];
         }

         return result;
     }

     private static string GetRequiredAuditValue(
         IReadOnlyDictionary<string, string> values,
         string[] args,
         int ordinal,
         string name)
     {
         if (values.TryGetValue(name, out var directValue))
         {
            return directValue;
         }

         var positionals = new List<string>();
         for (var i = 1; i < args.Length; i++)
         {
            if (!args[i].StartsWith("--", StringComparison.Ordinal))
            {
                positionals.Add(args[i]);
            }
         }

         if (ordinal >= positionals.Count)
         {
            throw new ArgumentException($"Missing required {name} value.");
         }

         return positionals[ordinal];
     }

     private sealed record CliOptions(
         DateOnly BusinessDate,
         string FixturesDirectory,
         string OutputDirectory,
         bool JsonOutput)
     {
         public static CliOptions Parse(string[] args)
         {
            var date = new DateOnly(2024, 6, 3);
            var baseDir = AppContext.BaseDirectory;
            var fixtures = Path.GetFullPath(Path.Combine(baseDir, "fixtures"));
            var output = Path.GetFullPath(Path.Combine(baseDir, "reports"));
            var json = false;

            for (var i = 0; i < args.Length; i++)
            {
                switch (args[i])
                {
                    case "--date":
                        date = DateOnly.ParseExact(NextValue(args, ref i, "--date"), "yyyy-MM-dd", CultureInfo.InvariantCulture);
                        break;
                    case "--fixtures":
                        fixtures = Path.GetFullPath(NextValue(args, ref i, "--fixtures"));
                        break;
                    case "--out":
                        output = Path.GetFullPath(NextValue(args, ref i, "--out"));
                        break;
                    case "--json":
                        json = true;
                        break;
                    default:
                        throw new ArgumentException($"Unknown argument '{args[i]}'.");
                }
            }

            return new CliOptions(date, fixtures, output, json);
         }

         private static string NextValue(string[] args, ref int index, string option)
         {
            if (index + 1 >= args.Length || args[index + 1].StartsWith("--", StringComparison.Ordinal))
            {
                throw new ArgumentException($"Option {option} requires a value.");
            }

            return args[++index];
         }
     }
 }

