1. using System.Collections.Concurrent;
2. using System.Globalization;
3. using System.Security.Cryptography;
4. using System.Text;
5. using System.Text.Json;
6. using System.Text.RegularExpressions;
7. 
8. namespace TradeRecon.Application.Audit;
9. 
10. public static partial class AuditCommandProcessor
11. {
12.     private static readonly ConcurrentDictionary<string, object> DirectoryLocks = new(StringComparer.OrdinalIgnoreCase);
13.     private static readonly JsonSerializerOptions JsonOptions = new()
14.     {
15.         PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
16.         WriteIndented = false
17.     };
18. 
19.     public static void Initialize(string stateDirectory)
20.     {
21.         ArgumentException.ThrowIfNullOrWhiteSpace(stateDirectory);
22. 
23.         var directory = EnsureDirectory(stateDirectory);
24.         var statePath = Path.Combine(directory, "audit-state.json");
25. 
26.         using var _ = AcquireLock(directory);
27.         if (!File.Exists(statePath))
28.         {
29.             WriteState(directory, new AuditState());
30.         }
31.     }
32. 
33.     public static AuditEntry Propose(
34.         string stateDirectory,
35.         string requestId,
36.         string proposer,
37.         DateOnly businessDate,
38.         string reason,
39.         string evidence)
40.     {
41.         ValidateRequestIdentity(requestId, nameof(requestId));
42.         ValidateActor(proposer, nameof(proposer));
43.         var sanitizedReason = SanitizeAuditText(reason);
44.         var sanitizedEvidence = SanitizeAuditText(evidence);
45.         if (string.IsNullOrWhiteSpace(sanitizedReason))
46.         {
47.             throw new ArgumentException("Reason must be provided.", nameof(reason));
48.         }
49. 
50.         if (string.IsNullOrWhiteSpace(sanitizedEvidence))
51.         {
52.             throw new ArgumentException("Evidence must be provided.", nameof(evidence));
53.         }
54. 
55.         var directory = EnsureDirectory(stateDirectory);
56.         using var _ = AcquireLock(directory);
57.         var state = LoadState(directory);
58.         var existing = state.Entries
59.             .Where(entry => entry.RequestId == requestId && entry.Action == AuditAction.Proposed)
60.             .OrderBy(entry => entry.Sequence)
61.             .LastOrDefault();
62. 
63.         if (existing is not null)
64.         {
65.             return existing;
66.         }
67. 
68.         var previousHash = state.Entries.Count == 0 ? null : state.Entries[^1].Hash;
69.         var nextSequence = state.Entries.Count == 0 ? 1 : state.Entries.Max(entry => entry.Sequence) + 1;
70.         var entry = new AuditEntry
71.         {
72.             RequestId = requestId,
73.             Action = AuditAction.Proposed,
74.             Actor = proposer,
75.             BusinessDate = businessDate,
76.             Reason = sanitizedReason,
77.             Evidence = sanitizedEvidence,
78.             Sequence = nextSequence,
79.             TimestampUtc = DateTimeOffset.UtcNow,
80.             Version = "1.0.0",
81.             PreviousHash = previousHash,
82.             Hash = string.Empty
83.         };
84. 
85.         entry.Hash = ComputeHash(entry);
86.         state.Entries.Add(entry);
87.         WriteState(directory, state);
88.         return entry;
89.     }
90. 
91.     public static AuditEntry Decide(
92.         string stateDirectory,
93.         string requestId,
94.         string approver,
95.         string decision)
96.     {
97.         ValidateRequestIdentity(requestId, nameof(requestId));
98.         ValidateActor(approver, nameof(approver));
99.         if (!Enum.TryParse<AuditDecision>(decision, true, out var parsedDecision))
100.         {
101.             throw new ArgumentException("Decision must be APPROVED or REJECTED.", nameof(decision));
102.         }
103. 
104.         var directory = EnsureDirectory(stateDirectory);
105.         using var _ = AcquireLock(directory);
106.         var state = LoadState(directory);
107.         var proposal = state.Entries
108.             .Where(entry => entry.RequestId == requestId && entry.Action == AuditAction.Proposed)
109.             .OrderBy(entry => entry.Sequence)
110.             .LastOrDefault();
111. 
112.         if (proposal is null)
113.         {
114.             throw new InvalidOperationException($"No proposal exists for requestId '{requestId}'.");
