1. using System.Globalization;
2. using System.Text.Json;
3. using Microsoft.Extensions.DependencyInjection;
4. using Microsoft.Extensions.Logging;
5. using Microsoft.Extensions.Logging.Console;
6. using TradeRecon.Application.Audit;
7. using TradeRecon.Application.Reconciliation;
8. using TradeRecon.Application.Reporting;
9. using TradeRecon.Domain;
10. using TradeRecon.Infrastructure;
11. 
12. namespace TradeRecon.Console;
13. 
14. /// <summary>
15. /// Console host for the canonical trade-reconciliation baseline. Runs a deterministic
16. /// end-of-day reconciliation over the synthetic CSV fixtures and writes the reports.
17. ///
18. /// This host exposes a stable, black-box-friendly CLI contract:
19. ///   * Inputs come from a fixture directory (--fixtures) containing trades.csv,
20. ///     settlements.csv and positions.csv.
21. ///   * Reports are written under --out/&lt;yyyy-MM-dd&gt;/ as eod-summary.txt,
22. ///     eod-break-register.csv and eod-result.json.
23. ///   * With --json the deterministic JSON result is written to stdout (and all logs are
24. ///     routed to stderr) so stdout contains nothing but the JSON document.
25. ///   * Exit codes: 0 = clean, 2 = breaks outstanding, 1 = input/processing error.
26. ///
27. /// Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures &lt;dir&gt;] [--out &lt;dir&gt;] [--json]
28. /// </summary>
29. public static class Program
30. {
31.     /// <summary>Reconciliation completed with no open breaks.</summary>
32.     public const int ExitClean = 0;
33. 
34.     /// <summary>Input or processing error (e.g. missing or malformed fixtures).</summary>
35.     public const int ExitError = 1;
36. 
37.     /// <summary>Reconciliation completed but open breaks remain.</summary>
38.     public const int ExitBreaks = 2;
39. 
40.     public static async Task<int> Main(string[] args)
41.     {
42.         if (args.Contains("--help") || args.Contains("-h"))
43.         {
44.             System.Console.WriteLine(
45.                 "Usage: TradeRecon.Console [--date yyyy-MM-dd] [--fixtures <dir>] [--out <dir>] [--json]");
46.             System.Console.WriteLine("Audit subcommands: audit initialize <stateDirectory> | audit propose <stateDirectory> <requestId> <proposer> <businessDate> <reason> <evidence> | audit decide <stateDirectory> <requestId> <approver> <decision> | audit export <stateDirectory> <fromDate> <toDate> <exportPath>");
47.             return ExitClean;
48.         }
49. 
50.         if (args.Length > 0 && (string.Equals(args[0], "audit", StringComparison.OrdinalIgnoreCase) || IsAuditVerb(args[0])))
51.         {
52.             return await RunAuditCommandAsync(args).ConfigureAwait(false);
53.         }
54. 
55.         CliOptions options;
56.         try
57.         {
58.             options = CliOptions.Parse(args);
59.         }
60.         catch (Exception ex) when (ex is FormatException or ArgumentException or PathTooLongException or NotSupportedException)
61.         {
62.             System.Console.Error.WriteLine($"Invalid arguments: {ex.Message}");
63.             return ExitError;
64.         }
65. 
66.         using var loggerFactory = LoggerFactory.Create(builder =>
67.         {
68.             builder.SetMinimumLevel(LogLevel.Information);
69.             builder.AddSimpleConsole(o =>
70.             {
71.                 o.SingleLine = true;
72.                 o.TimestampFormat = "HH:mm:ss ";
73.             });
74.             // In JSON mode keep stdout pure by sending every log line to stderr.
75.             if (options.JsonOutput)
76.             {
77.                 builder.Services.Configure<ConsoleLoggerOptions>(
78.                     o => o.LogToStandardErrorThreshold = LogLevel.Trace);
79.             }
80.         });
81. 
82.         var services = new ServiceCollection();
83.         services.AddSingleton<ILoggerFactory>(loggerFactory);
84.         services.AddLogging();
85.         services.AddTradeReconCore();
86.         services.AddTradeReconInfrastructure(options.FixturesDirectory, options.OutputDirectory);
87. 
88.         await using var provider = services.BuildServiceProvider();
89.         var logger = provider.GetRequiredService<ILogger<object>>();
90.         var runner = provider.GetRequiredService<ReconciliationRunner>();
91.         var reportBuilder = provider.GetRequiredService<EndOfDayReportBuilder>();
92. 
93.         var runOptions = new ReconciliationRunOptions
94.         {
